/**
 * Generates the conformance corpus (§9.5).
 *
 * **This file deliberately shares no code with `src/sdk`.** §9.5 rule 1:
 * expected values are computed from the specification, not captured from the
 * reference implementation — a corpus generated by the implementation it
 * certifies only proves the implementation agrees with itself. That is exactly
 * how r1's float-rounded SHA-1 buckets would have been baked in as "expected"
 * and then failed a correctly-implemented Go SDK (§9.4).
 *
 * So the murmur3 below is an independent, deliberately naive transcription of
 * the published algorithm: manual UTF-8 encoding (no `TextEncoder`) and BigInt
 * arithmetic (no `Math.imul`). It is slow and obvious. If it agrees with the
 * fast production implementation, that agreement means something.
 *
 * Run: node tools/gen-conformance.mjs
 */

import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);

const U32 = (1n << 32n) - 1n;

/** Manual UTF-8 encoding, per RFC 3629. No TextEncoder. */
function utf8Bytes(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  return out;
}

const mul = (a, b) => (a * b) & U32;
const rotl = (x, r) => ((x << BigInt(r)) | (x >> BigInt(32 - r))) & U32;

/** MurmurHash3 x86_32, transcribed from the reference pseudocode with BigInt. */
function murmur3(bytes, seed = 0) {
  const C1 = 0xcc9e2d51n;
  const C2 = 0x1b873593n;
  let h = BigInt(seed) & U32;
  const len = bytes.length;
  const blocks = len - (len % 4);

  for (let i = 0; i < blocks; i += 4) {
    let k =
      (BigInt(bytes[i]) |
        (BigInt(bytes[i + 1]) << 8n) |
        (BigInt(bytes[i + 2]) << 16n) |
        (BigInt(bytes[i + 3]) << 24n)) &
      U32;
    k = mul(k, C1);
    k = rotl(k, 15);
    k = mul(k, C2);
    h ^= k;
    h = rotl(h, 13);
    h = (mul(h, 5n) + 0xe6546b64n) & U32;
  }

  const rem = len % 4;
  if (rem > 0) {
    let k = 0n;
    if (rem > 2) k ^= BigInt(bytes[blocks + 2]) << 16n;
    if (rem > 1) k ^= BigInt(bytes[blocks + 1]) << 8n;
    k ^= BigInt(bytes[blocks]);
    k = mul(k, C1);
    k = rotl(k, 15);
    k = mul(k, C2);
    h ^= k;
  }

  h ^= BigInt(len);
  h ^= h >> 16n;
  h = mul(h, 0x85ebca6bn);
  h ^= h >> 13n;
  h = mul(h, 0xc2b2ae35n);
  h ^= h >> 16n;
  return h & U32;
}

/** Exact integer division, in BigInt so there is no float anywhere. */
function bucketOf(prefix, salt, value) {
  const raw = murmur3(utf8Bytes(`${prefix}.${salt}.${value}`));
  return Number((raw * 100000n) >> 32n);
}

/* ───────────────────────── bucketing.json ───────────────────────── */

const SALT = "conformance_salt";
const FLAG = "conformance-flag";

const handPicked = [
  // Plain ASCII.
  { prefix: FLAG, salt: SALT, value: "usr_1" },
  { prefix: FLAG, salt: SALT, value: "usr_2" },
  { prefix: FLAG, salt: SALT, value: "a" },
  { prefix: FLAG, salt: SALT, value: "" },
  { prefix: FLAG, salt: SALT, value: "x".repeat(200) },
  // Non-ASCII: the case where a charCodeAt implementation silently diverges
  // from every UTF-8 reader, and where random fixtures never land (§9.5 rule 2).
  { prefix: FLAG, salt: SALT, value: "usr_josé" },
  { prefix: "f", salt: SALT, value: "usr_josé" },
  { prefix: FLAG, salt: SALT, value: "日本語" },
  { prefix: FLAG, salt: SALT, value: "مرحبا" },
  { prefix: FLAG, salt: SALT, value: "🚀" },
  { prefix: FLAG, salt: SALT, value: "café_🚀_日" },
  // Combining characters: NFC and NFD are different byte sequences and MUST
  // bucket differently. Normalising in the SDK would be a silent spec change.
  { prefix: FLAG, salt: SALT, value: "é" },
  { prefix: FLAG, salt: SALT, value: "é" },
  // Seeded prefixes: a frozen experiment seed replaces the flag key, and
  // seed 0 must differ from an absent seed.
  { prefix: "0", salt: SALT, value: "usr_1" },
  { prefix: "42", salt: SALT, value: "usr_1" },
  // Salt separation: staging is not production.
  { prefix: FLAG, salt: "salt_staging", value: "usr_1" },
  { prefix: FLAG, salt: "salt_production", value: "usr_1" },
  // Separator handling: these must not collide with each other.
  { prefix: "a.b", salt: "c", value: "d" },
  { prefix: "a", salt: "b.c", value: "d" },
];

/**
 * Boundary-adjacent buckets, found by construction rather than hoped for.
 * These are the values where an off-by-one in `b < cursor` or a float cursor
 * changes the answer, and random fixtures never land on them.
 */
function findKeyWithBucket(prefix, target, limit = 5_000_000) {
  for (let i = 0; i < limit; i++) {
    const key = `probe_${i}`;
    if (bucketOf(prefix, SALT, key) === target) return key;
  }
  throw new Error(`no key found for bucket ${target} under prefix ${prefix}`);
}

const boundaryTargets = [0, 1, 9_999, 10_000, 10_001, 49_999, 50_000, 99_998, 99_999];
const boundaries = boundaryTargets.map((target) => ({
  prefix: FLAG,
  salt: SALT,
  value: findKeyWithBucket(FLAG, target),
  note: `boundary-adjacent: bucket ${target}`,
}));

/**
 * The evaluation corpus evaluates a flag keyed "f", and the flag key is part of
 * the hash prefix (§9.3) - so a boundary key found under `FLAG` is an ordinary
 * key under "f". These are found under the key the corpus actually uses.
 */
const EVAL_FLAG = "f";
const evalBoundary = Object.fromEntries(
  boundaryTargets.map((target) => [target, findKeyWithBucket(EVAL_FLAG, target)]),
);

const bucketing = {
  $comment:
    "Generated by tools/gen-conformance.mjs, which is an INDEPENDENT BigInt " +
    "transcription of the murmur3 spec sharing no code with src/sdk. " +
    "murmur3 x86_32 over the UTF-8 bytes of `${prefix}.${salt}.${value}`, " +
    "then floor(raw * 100000 / 2^32).",
  weightScale: 100000,
  hashSpace: 4294967296,
  cases: [...handPicked, ...boundaries].map((c) => ({
    ...c,
    expected: bucketOf(c.prefix, c.salt, c.value),
  })),
};

/* ───────────────────────── evaluation.json ───────────────────────── */

const at = (target) => evalBoundary[target];

const boolFlag = (over = {}) => ({
  key: "f",
  version: 1,
  kind: "boolean",
  on: true,
  variations: [false, true],
  offVariation: 0,
  fallthrough: { variation: 0 },
  prerequisites: [],
  targets: [],
  rules: [],
  ...over,
});

const snap = (flags, segments = {}) => ({
  version: 1,
  environmentKey: "production",
  salt: SALT,
  flags,
  segments,
});

/**
 * Expected outcomes here are derived from the precedence table in §9.1 by
 * hand — which variation and which reason, reasoned from the rules, not run
 * and recorded. The rollout cases use the boundary keys found above, so the
 * expected variation follows from `b < cursor` and the bucket integer that
 * `bucketing.json` independently pins.
 */
const evaluation = {
  $comment:
    "Expected values are derived from the §9.1 precedence table by hand. " +
    "Rollout expectations follow from the boundary buckets pinned in bucketing.json.",
  cases: [
    {
      name: "flag absent from the snapshot serves the caller default",
      flagKey: "missing",
      snapshot: snap({}),
      context: { key: "usr_1" },
      defaultValue: "CALLER_DEFAULT",
      expected: { value: "CALLER_DEFAULT", variationIndex: null, reason: "FLAG_NOT_FOUND" },
    },
    {
      name: "an off flag serves its off variation, outranking a matching rule",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          on: false,
          offVariation: 0,
          rules: [
            { id: "r0", variation: 1, clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["DE"], negate: false }] },
          ],
        }),
      }),
      context: { key: "usr_1", country: "DE" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "OFF" },
    },
    {
      name: "an off flag with no off variation serves the caller default",
      flagKey: "f",
      snapshot: snap({ f: boolFlag({ on: false, offVariation: null }) }),
      context: { key: "usr_1" },
      defaultValue: "CALLER_DEFAULT",
      expected: { value: "CALLER_DEFAULT", variationIndex: null, reason: "OFF" },
    },
    {
      name: "an unmet prerequisite serves the off variation",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({ prerequisites: [{ key: "p", variation: 1 }], fallthrough: { variation: 1 } }),
        p: boolFlag({ key: "p", fallthrough: { variation: 0 } }),
      }),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "PREREQUISITE_FAILED", prerequisiteKey: "p" },
    },
    {
      name: "a met prerequisite lets evaluation continue to the fallthrough",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({ prerequisites: [{ key: "p", variation: 1 }], fallthrough: { variation: 1 } }),
        p: boolFlag({ key: "p", fallthrough: { variation: 1 } }),
      }),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "FALLTHROUGH" },
    },
    {
      name: "an individual target outranks a matching rule",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          targets: [{ contextKind: "user", variation: 1, keys: ["usr_josé"] }],
          rules: [{ id: "r0", variation: 0, clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["DE"], negate: false }] }],
        }),
      }),
      context: { key: "usr_josé", country: "DE" },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "TARGET_MATCH" },
    },
    {
      name: "the first matching rule wins, and reports its index",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          rules: [
            { id: "r_a", variation: 0, clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["FR"], negate: false }] },
            { id: "r_b", variation: 1, clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["DE"], negate: false }] },
          ],
        }),
      }),
      context: { key: "usr_1", country: "DE" },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "RULE_MATCH", ruleIndex: 1, ruleId: "r_b" },
    },
    {
      name: "a rollout boundary bucket belongs to the LATER variation (b < cursor)",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          fallthrough: {
            rollout: {
              variations: [
                { variationIndex: 1, weight: 10000 },
                { variationIndex: 0, weight: 90000 },
              ],
            },
          },
        }),
      }),
      // bucket == 10000 exactly, so NOT < 10000: falls into variation 0.
      context: { key: at(10_000) },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "FALLTHROUGH" },
    },
    {
      name: "the bucket one below the boundary takes the earlier variation",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          fallthrough: {
            rollout: {
              variations: [
                { variationIndex: 1, weight: 10000 },
                { variationIndex: 0, weight: 90000 },
              ],
            },
          },
        }),
      }),
      context: { key: at(9_999) },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "FALLTHROUGH" },
    },
    {
      name: "the last bucket in the space still resolves",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          fallthrough: { rollout: { variations: [{ variationIndex: 0, weight: 99999 }, { variationIndex: 1, weight: 1 }] } },
        }),
      }),
      context: { key: at(99_999) },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "FALLTHROUGH" },
    },
    {
      name: "a rollout excludes a context that lacks the bucketing attribute",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          rules: [
            {
              id: "r0",
              rollout: { bucketBy: "accountId", variations: [{ variationIndex: 1, weight: 100000 }] },
              clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["DE"], negate: false }],
            },
          ],
          fallthrough: { variation: 0 },
        }),
      }),
      context: { key: "usr_1", country: "DE" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "FALLTHROUGH" },
    },
    {
      name: "a multi-context rollout buckets on the organization, not the user",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          fallthrough: {
            rollout: {
              contextKind: "organization",
              variations: [
                { variationIndex: 1, weight: 10000 },
                { variationIndex: 0, weight: 90000 },
              ],
            },
          },
        }),
      }),
      context: { kind: "multi", user: { key: "usr_1" }, organization: { key: at(9_999) } },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "FALLTHROUGH" },
    },
    {
      name: "a non-ASCII context key buckets by UTF-8 bytes",
      flagKey: "f",
      snapshot: snap({
        f: boolFlag({
          fallthrough: {
            rollout: {
              variations: [
                { variationIndex: 1, weight: 50000 },
                { variationIndex: 0, weight: 50000 },
              ],
            },
          },
        }),
      }),
      context: { key: "usr_josé" },
      defaultValue: null,
      // Bucketed under the flag key "f", per §9.3's `${prefix}.${salt}.${value}`.
      expected: {
        value: bucketOf(EVAL_FLAG, SALT, "usr_josé") < 50000,
        variationIndex: bucketOf(EVAL_FLAG, SALT, "usr_josé") < 50000 ? 1 : 0,
        reason: "FALLTHROUGH",
      },
    },
    {
      name: "a type mismatch serves the caller default rather than a wrong-typed value",
      flagKey: "f",
      snapshot: snap({ f: boolFlag({ variations: ["not a boolean"], fallthrough: { variation: 0 } }) }),
      context: { key: "usr_1" },
      defaultValue: false,
      expected: { value: false, variationIndex: null, reason: "ERROR", error: "WRONG_TYPE" },
    },
    {
      name: "an out-of-range variation index serves the caller default",
      flagKey: "f",
      snapshot: snap({ f: boolFlag({ fallthrough: { variation: 9 } }) }),
      context: { key: "usr_1" },
      defaultValue: false,
      expected: { value: false, variationIndex: null, reason: "ERROR", error: "VARIATION_OUT_OF_RANGE" },
    },
    /* ── the §22.3 fail-closed cases, in both polarities ── */
    {
      name: "POSITIVE segment clause does not match while membership is unresolved",
      flagKey: "f",
      snapshot: snap(
        {
          f: boolFlag({
            rules: [{ id: "r0", variation: 1, clauses: [{ contextKind: "user", attribute: "key", op: "segmentMatch", values: ["big"], negate: false }] }],
            fallthrough: { variation: 0 },
          }),
        },
        { big: { kind: "unresolvable", version: 1 } },
      ),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "FALLTHROUGH", unresolvedSegments: ["big"] },
    },
    {
      name: "NEGATED segment clause does not match while membership is unresolved",
      $comment:
        "The r2 leak. `NOT in big` with an unloaded cache evaluated the clause " +
        "to false, negate flipped it to TRUE, and every unconfirmed user was " +
        "served the gated feature. The rule must fail closed in BOTH polarities.",
      flagKey: "f",
      snapshot: snap(
        {
          f: boolFlag({
            rules: [{ id: "r0", variation: 1, clauses: [{ contextKind: "user", attribute: "key", op: "segmentMatch", values: ["big"], negate: true }] }],
            fallthrough: { variation: 0 },
          }),
        },
        { big: { kind: "unresolvable", version: 1 } },
      ),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "FALLTHROUGH", unresolvedSegments: ["big"] },
    },
    {
      name: "an unresolved rule does not block a later resolvable rule",
      flagKey: "f",
      snapshot: snap(
        {
          f: boolFlag({
            rules: [
              { id: "r0", variation: 0, clauses: [{ contextKind: "user", attribute: "key", op: "segmentMatch", values: ["big"], negate: true }] },
              { id: "r1", variation: 1, clauses: [{ contextKind: "user", attribute: "country", op: "in", values: ["DE"], negate: false }] },
            ],
            fallthrough: { variation: 0 },
          }),
        },
        { big: { kind: "unresolvable", version: 1 } },
      ),
      context: { key: "usr_1", country: "DE" },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "RULE_MATCH", ruleIndex: 1, ruleId: "r1", unresolvedSegments: ["big"] },
    },
    {
      name: "an inline segment resolves exactly, and negate inverts a real miss",
      flagKey: "f",
      snapshot: snap(
        {
          f: boolFlag({
            rules: [{ id: "r0", variation: 1, clauses: [{ contextKind: "user", attribute: "key", op: "segmentMatch", values: ["beta"], negate: true }] }],
            fallthrough: { variation: 0 },
          }),
        },
        { beta: { kind: "inline", version: 1, members: ["usr_other"] } },
      ),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: true, variationIndex: 1, reason: "RULE_MATCH", ruleIndex: 0, ruleId: "r0" },
    },
    {
      name: "exclusion beats inclusion in a segment",
      flagKey: "f",
      snapshot: snap(
        {
          f: boolFlag({
            rules: [{ id: "r0", variation: 1, clauses: [{ contextKind: "user", attribute: "key", op: "segmentMatch", values: ["beta"], negate: false }] }],
            fallthrough: { variation: 0 },
          }),
        },
        { beta: { kind: "inline", version: 1, members: ["usr_1"], excluded: ["usr_1"] } },
      ),
      context: { key: "usr_1" },
      defaultValue: null,
      expected: { value: false, variationIndex: 0, reason: "FALLTHROUGH" },
    },
  ],
};

/* ───────────────────────── cuckoo.json ───────────────────────── */

/**
 * The cuckoo fixture pins the HEADER by hand — magic, version, widths, sizing —
 * and lists known members and known non-members. The table bytes themselves are
 * produced by the encoder; a byte-exact table cannot be hand-computed, and
 * saying so is more useful than pretending otherwise. What a porting SDK
 * verifies is that it reads *these bytes* and finds *these members*, which is
 * the property that actually matters (§9.7).
 */
const cuckooMembers = [
  ...Array.from({ length: 1000 }, (_, i) => `usr_${i}`),
  "usr_josé",
  "日本語",
  "🚀",
];
const cuckooNonMembers = Array.from({ length: 1000 }, (_, i) => `ghost_${i}`);

const cuckoo = {
  $comment:
    "Header fields are specified by hand from §9.7. The table bytes are " +
    "encoder output: a porting SDK must read THESE bytes and find THESE " +
    "members. Parameters are frozen: (2,4) partial-key cuckoo, 16-bit " +
    "fingerprints, power-of-two buckets, i2 = i1 XOR h(fingerprint).",
  header: {
    magic: "FKCF",
    formatVersion: 1,
    fingerprintBits: 16,
    slotsPerBucket: 4,
    targetLoadFactor: 0.8,
    maxKicks: 500,
    // 1003 members / (4 * 0.8) = 313.4 -> 314 -> nextPow2 = 512 buckets.
    expectedBucketsLog2: 9,
    expectedByteLength: 16 + 512 * 8,
    seed: 0,
  },
  members: cuckooMembers,
  nonMembers: cuckooNonMembers,
  /**
   * The encoded filter itself, base64.
   *
   * The `$comment` above promised that a porting SDK reads *these bytes*, and
   * until this field existed the corpus shipped no bytes to read — so the one
   * claim the fixture was making about the wire format was the one thing it did
   * not test. The Python conformance runner decodes this and looks every member
   * up; that is what makes the format frozen rather than merely documented.
   *
   * Encoder output by necessity: a byte-exact cuckoo table cannot be
   * hand-derived, and pretending otherwise would be worse than saying so.
   */
  filterBase64: encodeCuckooFixture(cuckooMembers),
};

/**
 * Build the fixture filter with the shipped encoder.
 *
 * The only place in this generator that touches `src/sdk`, and it is
 * deliberate: every *expected value* here is derived from the specification,
 * but a wire format's bytes have to come from an encoder. What the corpus
 * certifies is that an independent decoder reads them correctly.
 */
function encodeCuckooFixture(members) {
  const { buildCuckooFilter } = require("../dist/sdk/evaluation/cuckoo.js");
  const built = buildCuckooFilter(members, { fingerprintBits: 16, loadFactor: 0.8 });
  return Buffer.from(built.filter.encode()).toString("base64");
}

const outDir = join(process.cwd(), "tests/conformance");
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "bucketing.json"), JSON.stringify(bucketing, null, 2) + "\n");
writeFileSync(join(outDir, "evaluation.json"), JSON.stringify(evaluation, null, 2) + "\n");
writeFileSync(join(outDir, "cuckoo.json"), JSON.stringify(cuckoo, null, 2) + "\n");

console.log(
  `wrote ${bucketing.cases.length} bucketing cases, ${evaluation.cases.length} evaluation cases, ` +
    `${cuckoo.members.length} cuckoo members`,
);
